#!/usr/bin/env python3
"""Original Islamic-geometry art for Sakina — all vector, generated by code (no image generator).
Outputs: app/public/art/*.svg (used in-app) and brand/out/art/*.svg (hero scenes for rendering to 4K)."""
import os, math
HERE = os.path.dirname(__file__)
APP_ART = os.path.join(HERE, '..', 'app', 'public', 'art')
OUT_ART = os.path.join(HERE, 'out', 'art')
os.makedirs(APP_ART, exist_ok=True); os.makedirs(OUT_ART, exist_ok=True)
EMERALD, GOLD, IVORY, NIGHT = '#174B3C', '#C9A24D', '#F7F4EC', '#101C18'

def star8(cx, cy, r_out, r_in):
    pts = []
    for i in range(16):
        a = math.pi / 8 * i - math.pi / 2
        r = r_out if i % 2 == 0 else r_in
        pts.append(f"{cx + r*math.cos(a):.2f},{cy + r*math.sin(a):.2f}")
    return 'M' + ' L'.join(pts) + ' Z'

# 1) Seamless 8-point star + cross tessellation (classic khatam), drawn as thin strokes in currentColor so it tints with the theme.
def pattern_star_tile(size=120):
    s = size; h = s / 2
    body = []
    # star at centre and quarter-stars at corners → seamless
    for (cx, cy) in [(h, h), (0, 0), (s, 0), (0, s), (s, s)]:
        body.append(f'<path d="{star8(cx, cy, h*0.62, h*0.26)}"/>')
    # connecting cross (octagon ring) between stars
    body.append(f'<path d="{star8(h, 0, h*0.3, h*0.12)}"/><path d="{star8(0, h, h*0.3, h*0.12)}"/><path d="{star8(s, h, h*0.3, h*0.12)}"/><path d="{star8(h, s, h*0.3, h*0.12)}"/>')
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {s} {s}" width="{s}" height="{s}"><g fill="none" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round">{"".join(body)}</g></svg>'

# 2) Mashrabiya lattice (turned-wood screen abstraction): hexagonal-ish lattice of rounded lozenges.
def pattern_mashrabiya(size=80):
    s = size; h = s / 2
    d = []
    for (cx, cy) in [(h, h), (0, 0), (s, 0), (0, s), (s, s)]:
        d.append(f'<path d="M{cx} {cy-h*0.55} L{cx+h*0.5} {cy} L{cx} {cy+h*0.55} L{cx-h*0.5} {cy} Z"/>')
        d.append(f'<circle cx="{cx}" cy="{cy}" r="{h*0.16}"/>')
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {s} {s}" width="{s}" height="{s}"><g fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round">{"".join(d)}</g></svg>'

# 3) Arch band: a row of pointed arches (mihrab rhythm) for headers — stroke only, currentColor.
def arch_band(w=1200, h=160, n=7):
    pitch = w / n
    d = []
    for i in range(n):
        x0 = i * pitch + pitch * 0.12; x1 = (i + 1) * pitch - pitch * 0.12; cx = (x0 + x1) / 2
        half = (x1 - x0) / 2; r = half * 2
        top = h * 0.22
        # pointed arch: two arcs from the feet meeting at the apex (radius = width → equilateral-ish)
        d.append(f'<path d="M{x0:.1f} {h} L{x0:.1f} {h*0.62:.1f} A{r:.1f} {r:.1f} 0 0 1 {cx:.1f} {top:.1f} A{r:.1f} {r:.1f} 0 0 1 {x1:.1f} {h*0.62:.1f} L{x1:.1f} {h}"/>')
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" width="{w}" height="{h}" preserveAspectRatio="xMidYMax slice"><g fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round">{"".join(d)}</g></svg>'

# 4) Dome silhouette (single) for seasonal/welcome areas.
def dome(w=600, h=420):
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" width="{w}" height="{h}"><g fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round" stroke-linecap="round">
<path d="M120 {h} L120 300 C120 170 220 100 300 60 C380 100 480 170 480 300 L480 {h}"/>
<path d="M300 60 L300 18"/><path d="{star8(300, 10, 10, 4)}" fill="currentColor" stroke="none"/>
<path d="M60 {h} L60 350 A30 30 0 0 1 120 350"/><path d="M540 {h} L540 350 A30 30 0 0 0 480 350"/>
</g></svg>'''

def write(path, s):
    with open(path, 'w', encoding='utf-8') as f: f.write(s)

write(os.path.join(APP_ART, 'pattern-star.svg'), pattern_star_tile())
write(os.path.join(APP_ART, 'pattern-mashrabiya.svg'), pattern_mashrabiya())
write(os.path.join(APP_ART, 'arch-band.svg'), arch_band())
write(os.path.join(APP_ART, 'dome.svg'), dome())
for n in ('pattern-star', 'pattern-mashrabiya', 'arch-band', 'dome'):
    write(os.path.join(OUT_ART, n + '.svg'), open(os.path.join(APP_ART, n + '.svg'), encoding='utf-8').read())

# 5) Hero scenes (landscape 3840×2160, portrait 2160×3840): ivory paper, soft emerald light from a mihrab arch,
#    star lattice at low opacity, logo mark. No text, no verses, nothing busy behind content.
mark = open(os.path.join(HERE, 'out', 'svg', 'sakina-mark-green-gold.svg'), encoding='utf-8').read()
mark_inner = mark[mark.index('>') + 1: mark.rindex('</svg>')]
def hero(W, H, dark=False):
    bg = NIGHT if dark else IVORY
    ink = IVORY if dark else EMERALD
    tile = pattern_star_tile(160).replace('<svg ', '<svg id="t" ')
    tile_inner = tile[tile.index('>') + 1: tile.rindex('</svg>')]
    cx, cy = W / 2, H * (0.56 if W > H else 0.5)
    R = min(W, H) * 0.42
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}">
<defs>
  <pattern id="p" width="160" height="160" patternUnits="userSpaceOnUse"><g color="{ink}" opacity="{0.10 if dark else 0.08}">{tile_inner}</g></pattern>
  <radialGradient id="glow" cx="{cx}" cy="{cy}" r="{R*1.6}" gradientUnits="userSpaceOnUse">
    <stop offset="0" stop-color="{'#2B6B55' if dark else '#DCE8E1'}" stop-opacity="0.9"/><stop offset="0.55" stop-color="{'#2B6B55' if dark else '#DCE8E1'}" stop-opacity="0.35"/><stop offset="1" stop-color="{bg}" stop-opacity="0"/>
  </radialGradient>
  <linearGradient id="paper" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="{bg}"/><stop offset="1" stop-color="{'#0C1613' if dark else '#EFEAE0'}"/></linearGradient>
</defs>
<rect width="{W}" height="{H}" fill="url(#paper)"/>
<rect width="{W}" height="{H}" fill="url(#p)"/>
<circle cx="{cx}" cy="{cy}" r="{R*1.6}" fill="url(#glow)"/>
<g fill="none" stroke="{ink}" stroke-width="{max(6, R*0.012)}" opacity="0.55" stroke-linecap="round">
  <path d="M{cx-R*1.1} {cy+R*1.05} L{cx-R*1.1} {cy+R*0.1} A{R*2.2} {R*2.2} 0 0 1 {cx} {cy-R*0.95} A{R*2.2} {R*2.2} 0 0 1 {cx+R*1.1} {cy+R*0.1} L{cx+R*1.1} {cy+R*1.05}"/>
  <path d="M{cx-R*1.4} {cy+R*1.05} L{cx+R*1.4} {cy+R*1.05}"/>
</g>
<g transform="translate({cx-R*0.5},{cy-R*0.55}) scale({R/1000})">{mark_inner.replace(EMERALD, ink)}</g>
</svg>'''
write(os.path.join(OUT_ART, 'hero-landscape-3840x2160.svg'), hero(3840, 2160))
write(os.path.join(OUT_ART, 'hero-portrait-2160x3840.svg'), hero(2160, 3840))
write(os.path.join(OUT_ART, 'hero-landscape-dark-3840x2160.svg'), hero(3840, 2160, True))
write(os.path.join(OUT_ART, 'hero-portrait-dark-2160x3840.svg'), hero(2160, 3840, True))
print('art written')
